// Writes character save data to a .d2s file in the save directory. Retrieves the save path, constructs the full file path with character name, calculates checksum for the save file header, and writes the entire save structure (0x14f bytes) to disk. Returns 1 on success, 0 if file creation fails.
uint32_t __fastcall LAUNCHER_WriteSaveFileToD2s(char * szCharacterName) {
    char szSavePathBuffer[1024];
    char szFullFilePath[500];
    uint32_t dwBytesWritten;
    Fog::Source::SFile::GetAndCreateSavePath(szSavePathBuffer, 0x400);
    sprintf(szFullFilePath, "%s%s.d2s", szSavePathBuffer, szCharacterName);
    HANDLE hFile = Fog::Source::SFile::thunk_CreateFileA(szFullFilePath, 0x40000000, 0, (LPSECURITY_ATTRIBUTES)0x0, 2, 0x8000000, (HANDLE)0x0);
    if (!hFile) {
      return 0;
    }

    SAVEFILE.dwChecksum = Fog::Save::CalculateChecksum((uint8_t*)&SAVEFILE, 0x14f);
    Fog::Source::SFile::thunk_WriteFile(hFile, (LPCVOID)&SAVEFILE, 0x14f, (LPDWORD)&dwBytesWritten, (LPOVERLAPPED)0x0);
    Fog::Source::SFile::SFILE_Win32CloseHandle(hFile);
    return 1;
}

// Deletes all files associated with a character in the save directory. Constructs a search pattern "savepath\character.*" and iterates through all matching files, skipping directories, deleting each file found. If a subdirectory is specified, creates and operates within that subdirectory. Halts with unrecoverable error if character name is empty.
void __fastcall LAUNCHER_DeleteCharacterFiles(D2CharSelStrc * pCharSel, char * szSubdirectory) {
    DWORD dwFileAttributes;
    BOOL bSuccess;
    char szSearchPattern[500];
    char szFullFilePath[500];
    char szSubdirPath[260];
    _WIN32_FIND_DATAA findData;
    char szSavePath[260];
    if (pCharSel->szCharname[0] == '\0') {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0xaf);
      exit(-1);
    }

    Fog::Source::SFile::GetAndCreateSavePath(szSavePath, 0x104);
    if (szSubdirectory && *szSubdirectory != '\0') {
      Storm::Source::SSTR::SStrPrintf(szSubdirPath, 0x104, "%s%s\\", szSavePath, szSubdirectory);
      Fog::Source::SFile::SafeCreateDirectoryTree(szSubdirPath);
      Storm::Source::SSTR::SStrCopy(szSavePath, szSubdirPath, 0x104);
    }

    sprintf(szSearchPattern, "%s%s.*", szSavePath, pCharSel->szCharname);
    HANDLE hFindFile = FindFirstFileA(szSearchPattern, &findData);
    while (true) {
      while (true) {
        if (hFindFile == (HANDLE)-1) {
          return;
        }

        sprintf(szFullFilePath, "%s%s", szSavePath, findData.cFileName);
        /* LPCSTR lpFileName for GetFileAttributesA */ dwFileAttributes = GetFileAttributesA(szFullFilePath);
        if (!(dwFileAttributes & 0x10)) {
          break;
        }

        /* LPWIN32_FIND_DATAA lpFindFileData for FindNextFileA */ /* HANDLE hFindFile for FindNextFileA */ bSuccess = FindNextFileA(hFindFile, &findData);
        if (!bSuccess) {
          return;
        }
      }

      /* LPCSTR lpFileName for DeleteFileA */ bSuccess = DeleteFileA(szFullFilePath);
      if (!bSuccess) {
        break;
      }

      /* LPWIN32_FIND_DATAA lpFindFileData for FindFirstFileA */ /* LPCSTR lpFileName for FindFirstFileA */ hFindFile = FindFirstFileA(szSearchPattern, &findData);
    }
}

// Loads character appearance data from a .d2s save file for display in character selection. Reads up to 8KB from the save file, validates the magic number (0xaa55aa55), extracts equipment and visual data based on save file version (pre-0x5c vs 0x5c-0x60), and writes encoded appearance info to output buffer including class, level, and equipped items. Returns 1 on success, 0 on failure.
uint32_t __fastcall LAUNCHER_LoadCharacterAppearanceFromD2s(char * szCharacterName, uint8_t * pOutputBuffer) {
    int i;
    char* pbEquipSrc;
    uint8_t byOutPlayerClass;
    uint8_t cPlayerClass;
    uint8_t* pbWritePtr;
    uint8_t* pbVisualSrc;
    D2SaveFileBufferStrc sSaveFile;
    char szSavePathBuffer[1024];
    char szFilePath[500];
    FILE* pFile;
    uint32_t nLevel;
    uint8_t* pEquipmentData;
    uint8_t byCopyTmp;
    uint32_t dwCopyTmp;
    uint32_t dwCopyTmp2;
    uint16_t wCopyTmp;
    uint32_t nResult;
    nResult = 0;
    if (*szCharacterName == '\0') {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", (void*)(int32_t)Fog::Src::ErrorManager::GetInstructionPointer(), 0xe9);
      exit(-1);
    }

    Fog::Source::SFile::GetAndCreateSavePath(szSavePathBuffer, 0x400);
    sprintf(szFilePath, "%s%s.d2s", szSavePathBuffer, szCharacterName);
    FILE* pSaveFile;
    pSaveFile = fopen(szFilePath, "rb");
    if (!pSaveFile) {
      return 0;
    }

    size_t nBytesRead;
    nBytesRead = fread((D2CharSelCompStrc*)&sSaveFile, 1, 0x2000, pSaveFile);
    if (nBytesRead >= 8 && sSaveFile.sHeader.dwHeader == 0xaa55aa55) {
      if (sSaveFile.sHeader.dwFileVersion <= 0x5b) {
        if (nBytesRead < 0x82 || sSaveFile.sHeader.dwFileVersion < 0x47) {
          goto cleanup;
        }

        pbEquipSrc = (char*)((uintptr_t)&sSaveFile.sHeader.dwCharacterStatus + 2);
        pbVisualSrc = (uint8_t*)((uintptr_t)&sSaveFile.sHeader.nTimeEx + 2);
        cPlayerClass = sSaveFile.sHeader.szCharacterName[0xe];
        byOutPlayerClass = (uint8_t)sSaveFile.sHeader.dwCharacterStatus;
      } else {
        if (nBytesRead < 0x14f || sSaveFile.sHeader.dwFileVersion > 0x60) {
          goto cleanup;
        }

        pbEquipSrc = sSaveFile.sHeader.pAppearance1;
        pbVisualSrc = (uint8_t*)sSaveFile.sHeader.pAppearance2;
        cPlayerClass = sSaveFile.sHeader.nPlayerClassId;
        byOutPlayerClass = sSaveFile.sHeader.bCharacterLevel;
        *(uint16_t*)((char*)&sSaveFile.sHeader.szCharacterName + 4) = (uint16_t)sSaveFile.sHeader.dwCharacterStatus;
      }

      D2Game::Save::SAVEFILE_WriteEncodedInt14Bit(pOutputBuffer, 0xe);
      pbWritePtr = pOutputBuffer + 2;
      if (*pbEquipSrc == '\0') {
        i = 0;
        do {
          *pbWritePtr = gaNewCharDefaultAppearance[i];
          i++;
          pbWritePtr++;
        } while (i < 0xb);
      } else {
        dwCopyTmp = *(uint32_t*)(pbEquipSrc + 4);
        *(uint32_t*)pbWritePtr = *(uint32_t*)pbEquipSrc;
        wCopyTmp = *(uint16_t*)(pbEquipSrc + 8);
        byCopyTmp = pbEquipSrc[10];
        *(uint32_t*)(pOutputBuffer + 6) = dwCopyTmp;
        *(uint16_t*)(pOutputBuffer + 10) = wCopyTmp;
        pOutputBuffer[0xc] = byCopyTmp;
        pbWritePtr = pOutputBuffer + 0xd;
      }

      dwCopyTmp = *(uint32_t*)pbVisualSrc;
      dwCopyTmp2 = *(uint32_t*)(pbVisualSrc + 4);
      wCopyTmp = *(uint16_t*)(pbVisualSrc + 8);
      *pbWritePtr = cPlayerClass + 1;
      *(uint32_t*)(pbWritePtr + 1) = dwCopyTmp;
      cPlayerClass = pbVisualSrc[10];
      *(uint32_t*)(pbWritePtr + 5) = dwCopyTmp2;
      *(uint16_t*)(pbWritePtr + 9) = wCopyTmp;
      pbWritePtr[0xb] = cPlayerClass;
      pbWritePtr[0xc] = byOutPlayerClass;
      D2Game::Save::SAVEFILE_WriteEncodedInt14Bit(pbWritePtr + 0xd, (uint32_t)(uint16_t)*(uint16_t*)((char*)&sSaveFile.sHeader.szCharacterName + 4));
      D2Game::Save::SAVEFILE_WriteEncodedInt14Bit(pbWritePtr + 0xf, 0);
      pbWritePtr[0x11] = 0xff;
      pbWritePtr[0x12] = 0xff;
      pbWritePtr[0x13] = 0xff;
      pbWritePtr[0x14] = 0;
      nResult = 1;
    }

    cleanup:
    fclose(pSaveFile);
    return nResult;
}

BOOL __fastcall UpdateSaveFileToExpansion(char * szCharname) {
    // Frame slots -16..-4 are ONE object: &dwExpansionFlag is passed out and the callee reaches the rest by byte offset.
    // Separate locals let the compiler reorder them, so the run is one struct.
    struct __frame0_t {
      uint32_t dwExpansionFlag;
      DWORD dwBytesWritten;
      DWORD dwBytesRead;
    };
    static_assert(sizeof(void*) != 4 || sizeof(__frame0_t) == 12, "frame group __frame0_t must reproduce the Ghidra frame layout");
    __frame0_t __frame0;
    D2SaveFileBufferStrc* lpBuffer;
    D2SaveFileBufferStrc sSaveFile;
    char szSavePathBuffer[1024];
    char szFilePath[500];
    DWORD nNumberOfBytesToWrite;
    __frame0.dwBytesRead = 0x43caad;
    Fog::Source::SFile::GetAndCreateSavePath(szSavePathBuffer, 0x400);
    sprintf(szFilePath, "%s%s.d2s", szSavePathBuffer, szCharname);
    HANDLE hFile = Fog::Source::SFile::thunk_CreateFileA(szFilePath, 0xc0000000, 0, (LPSECURITY_ATTRIBUTES)0x0, 3, 0x8000000, (HANDLE)0x0);
    if (!hFile) {
      return 0;
    }

    Fog::Source::SFile::thunk_ReadFile(hFile, &sSaveFile, 0x2000, &__frame0.dwBytesRead, (LPOVERLAPPED)0x0);
    if (!(__frame0.dwBytesRead >= 8 && sSaveFile.sHeader.dwHeader == 0xaa55aa55)) {
      return 0;
    }
    if (sSaveFile.sHeader.dwFileVersion <= 0x5b) {
      if (__frame0.dwBytesRead < 0x82) {
        return 0;
      }

      __frame0.dwExpansionFlag = *(uint32_t*)((char*)&sSaveFile.sHeader.szCharacterName + 4) | 0x20;
      Fog::Source::SFile::SFILE_Win32SetFilePointer(hFile, 0x18, (PLONG)0x0, 0);
      lpBuffer = (D2SaveFileBufferStrc*)&__frame0.dwExpansionFlag;
      nNumberOfBytesToWrite = 4;
    } else {
      if (__frame0.dwBytesRead < 0x14f) {
        return 0;
      }

      sSaveFile.sHeader.dwCharacterStatus |= 0x20;
      sSaveFile.sHeader.dwChecksum = 0;
      sSaveFile.sHeader.dwChecksum = Fog::Save::CalculateChecksum((uint8_t*)&sSaveFile, __frame0.dwBytesRead);
      Fog::Source::SFile::SFILE_Win32SetFilePointer(hFile, 0, (PLONG)0x0, 0);
      lpBuffer = &sSaveFile;
      nNumberOfBytesToWrite = __frame0.dwBytesRead;
    }

    BOOL bWriteSuccess = Fog::Source::SFile::thunk_WriteFile(hFile, (LPCVOID)lpBuffer, nNumberOfBytesToWrite, &__frame0.dwBytesWritten, (LPOVERLAPPED)0x0);
    Fog::Source::SFile::SFILE_Win32CloseHandle(hFile);
    return bWriteSuccess;
}

